import { reflectPosition } from "./advanced";
import { sampleLocus } from "./locus";
import { equation, evaluate } from "./expression";
import type { DrawingCurve, Vec2 } from "./types";
import { sampleParametric } from "./parametric";
import { conicCoefficients } from "./conics";
export interface CurveResult {
  id: string;
  paths: Vec2[][];
  error?: string;
}
/** Only migrate equations generated by the old preset buttons; preserve custom source. */
export function compactPresetEquation(curve: DrawingCurve): string {
  const p = curve.preset;
  if (!p) return curve.equation;
  const rad = p.angle * Math.PI / 180, c = Math.cos(rad), s = Math.sin(rad);
  const x = `((x-(${p.h}))*(${c})+(y-(${p.k}))*(${s}))`;
  const y = `(-(x-(${p.h}))*(${s})+(y-(${p.k}))*(${c}))`;
  const old = p.type === "circle" ? `(x-(${p.h}))^2+(y-(${p.k}))^2=(${p.a})^2`
    : p.type === "ellipse" ? `\\frac{${x}^2}{(${p.a})^2}+\\frac{${y}^2}{(${p.b})^2}=1`
    : p.type === "hyperbola" ? `\\frac{${x}^2}{(${p.a})^2}-\\frac{${y}^2}{(${p.b})^2}=1`
    : `${y}^2=2*(${p.a})*${x}`;
  return curve.equation.replace(/\s/g, "") === old ? presetEquation(p) : curve.equation;
}
export function presetEquation(p: NonNullable<DrawingCurve["preset"]>): string {
  const fmt = (n: number) => String(Number(n.toPrecision(12)));
  const shift = (name: string, n: number) => n === 0 ? name : `(${name}${n < 0 ? "+" : "-"}${fmt(Math.abs(n))})`;
  const u = shift("x", p.h), v = shift("y", p.k);
  const rad = (p.angle * Math.PI) / 180;
  const coefficient = (n: number) => Math.abs(n) < 1e-12 ? 0 : Number(n.toPrecision(12));
  const c = coefficient(Math.cos(rad)), s = coefficient(Math.sin(rad));
  const linear = (a: number, b: number) => {
    const terms = [[a, u], [b, v]].filter(([n]) => n !== 0) as [number, string][];
    const text = terms.map(([n, t], i) => `${n < 0 ? "-" : i ? "+" : ""}${Math.abs(n) === 1 ? "" : fmt(Math.abs(n))}${t}`).join("");
    return terms.length > 1 ? `(${text})` : text.startsWith("-") ? `(${text})` : text;
  };
  const x = linear(c, s), y = linear(-s, c);
  const fraction = (t: string, a: number) => a === 1 ? `${t}^2` : `\\frac{${t}^2}{${fmt(a * a)}}`;
  if (p.type === "circle") return `${u}^2+${v}^2=${fmt(p.a * p.a)}`;
  if (p.type === "ellipse") return `${fraction(x, p.a)}+${fraction(y, p.b)}=1`;
  if (p.type === "hyperbola") return `${fraction(x, p.a)}-${fraction(y, p.b)}=1`;
  const a = 2 * p.a;
  return `${y}^2=${a === 1 ? "" : a === -1 ? "-" : fmt(a)}${x}`;
}
export function sampleCurve(
  curve: DrawingCurve,
  range = curve.range,
  resolution = 180,
  budgetMs = 800,
): CurveResult {
  const limits=curve.limits;
  range=[Math.max(range[0],limits?.xMin??-Infinity),Math.min(range[1],limits?.xMax??Infinity),Math.max(range[2],limits?.yMin??-Infinity),Math.min(range[3],limits?.yMax??Infinity)];
  if(range[0]>=range[1]||range[2]>=range[3]) return {id:curve.id,paths:[]};
  if(curve.reflectionInput) {
    const r=curve.reflectionInput,corners:Vec2[]=[[range[0],range[2]],[range[0],range[3]],[range[1],range[2]],[range[1],range[3]]],inverse=corners.map(p=>reflectPosition(p,r.a,r.b));
    const xs=inverse.map(p=>p[0]),ys=inverse.map(p=>p[1]),bounds:[number,number,number,number]=[Math.min(...xs),Math.max(...xs),Math.min(...ys),Math.max(...ys)];
    if(r.source.followView===false){bounds[0]=Math.max(bounds[0],r.source.range[0]);bounds[1]=Math.min(bounds[1],r.source.range[1]);bounds[2]=Math.max(bounds[2],r.source.range[2]);bounds[3]=Math.min(bounds[3],r.source.range[3]);}
    const original=sampleCurve(r.source,bounds,resolution,budgetMs);
    return {id:curve.id,paths:clipPaths(original.paths.map(path=>path.map(p=>reflectPosition(p,r.a,r.b))),range),error:original.error};
  }

  if(curve.locusInput) {const c=curve.locusInput;return {id:curve.id,paths:clipPaths(sampleLocus(c.document,c.driver,c.follower,curve.planeId,c.min,c.max,budgetMs),range)};}
  if(!curve.parametric) {
    const q=conicCoefficients(curve.equation);
    if(q && q.slice(0,3).every(v=>v===0)) {
      const [,,,a,b,c]=q,[xmin,xmax,ymin,ymax]=range,points:Vec2[]=[];
      const accept=(x:number,y:number)=>{
        if(x>=xmin-1e-8&&x<=xmax+1e-8&&y>=ymin-1e-8&&y<=ymax+1e-8&&!points.some(p=>Math.hypot(p[0]-x,p[1]-y)<1e-8))points.push([x,y]);
      };
      if(b!==0)for(const x of [xmin,xmax])accept(x,-(a*x+c)/b);
      if(a!==0)for(const y of [ymin,ymax])accept(-(b*y+c)/a,y);
      return {id:curve.id,paths:points.length>=2?[points.slice(0,2)]:[]};
    }
  }
  const started = performance.now(),
    parsed = equation(curve.equation),
    [xmin, xmax, ymin, ymax] = range,
    paths: Vec2[][] = [];
  const fn = (x: number, y: number) =>
    evaluate(parsed.ast, { x, y, u: x, v: y });
  const guard = () => {
    if (performance.now() - started > budgetMs)
      throw new Error("曲线计算超时，请缩小绘图区间或简化表达式");
  };
  if(curve.parametric) paths.push(...sampleParametric(curve,range,budgetMs,resolution));
  else if (parsed.type !== "implicit") {
    const lo = parsed.type === "y" ? xmin : ymin,
      hi = parsed.type === "y" ? xmax : ymax,
      span = parsed.type === "y" ? ymax - ymin : xmax - xmin;
    let current: Vec2[] = [];
    const append = (t: number, v: number) => {
      const p: Vec2 = parsed.type === "y" ? [t, v] : [v, t];
      if (Number.isFinite(v) && Math.abs(v) < 1e8) current.push(p);
      else {
        if (current.length > 1) paths.push(current);
        current = [];
      }
    };
    const split = () => {
      if (current.length > 1) paths.push(current);
      current = [];
    };
    const value = (t: number) => (parsed.type === "y" ? fn(t, 0) : fn(0, t));
    const segment = (
      a: number,
      b: number,
      fa: number,
      fb: number,
      depth: number,
    ) => {
      const m = (a + b) / 2,
        fm = value(m),
        good = [fa, fb, fm].every(Number.isFinite);
      if (
        !good ||
        Math.abs(fb - fa) > span * 0.25 ||
        Math.abs(fm - (fa + fb) / 2) > span * 0.005
      ) {
        if (depth < 9) {
          segment(a, m, fa, fm, depth + 1);
          segment(m, b, fm, fb, depth + 1);
        } else if (good && Math.abs(fb - fa) < span * 0.5) append(b, fb);
        else split();
      } else append(b, fb);
    };
    let a = lo,
      fa = value(a);
    append(a, fa);
    for (let i = 1; i <= resolution; i++) {
      if (i % 16 === 0) guard();
      const b = lo + ((hi - lo) * i) / resolution,
        fb = value(b);
      segment(a, b, fa, fb, 0);
      a = b;
      fa = fb;
    }
    split();
  } else {
    const n = Math.max(24, Math.min(240, resolution)),
      dx = (xmax - xmin) / n,
      dy = (ymax - ymin) / n;
    const values = new Float64Array((n + 1) * (n + 1));
    for (let j = 0; j <= n; j++) {
      if (j % 8 === 0) guard();
      for (let i = 0; i <= n; i++)
        values[j * (n + 1) + i] = fn(xmin + i * dx, ymin + j * dy);
    }
    const root = (a: Vec2, b: Vec2, fa: number, fb: number): Vec2 | null => {
      if (!Number.isFinite(fa) || !Number.isFinite(fb) || fa * fb > 0)
        return null;
      if (fa === 0) return a;
      if (fb === 0) return b;
      let l = 0,
        r = 1,
        fl = fa,
        t = 0.5,
        fm = NaN;
      for (let k = 0; k < 32; k++) {
        t = (l + r) / 2;
        fm = fn(a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t);
        if (!Number.isFinite(fm)) return null;
        if (fm > 0 === fl > 0) {
          l = t;
          fl = fm;
        } else r = t;
      }
      if (
        Math.abs(fm) >
        Math.max(1e-6, Math.min(Math.abs(fa), Math.abs(fb)) * 0.001)
      )
        return null;
      return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t];
    };
    for (let j = 0; j < n; j++) {
      if (j % 8 === 0) guard();
      for (let i = 0; i < n; i++) {
        const x = xmin + i * dx,
          y = ymin + j * dy,
          p: Vec2[] = [
            [x, y],
            [x + dx, y],
            [x + dx, y + dy],
            [x, y + dy],
          ],
          v = [
            values[j * (n + 1) + i],
            values[j * (n + 1) + i + 1],
            values[(j + 1) * (n + 1) + i + 1],
            values[(j + 1) * (n + 1) + i],
          ];
        const roots: Vec2[] = [];
        for (let k = 0; k < 4; k++) {
          const r = root(p[k], p[(k + 1) % 4], v[k], v[(k + 1) % 4]);
          if (
            r &&
            !roots.some((q) => Math.hypot(q[0] - r[0], q[1] - r[1]) < 1e-8)
          )
            roots.push(r);
        }
        if (roots.length === 2) paths.push(roots);
        else if (roots.length === 4) {
          const center = fn(x + dx / 2, y + dy / 2);
          if (center > 0 === v[0] > 0) {
            paths.push([roots[0], roots[1]], [roots[2], roots[3]]);
          } else paths.push([roots[0], roots[3]], [roots[1], roots[2]]);
        }
      }
    }
  }
  return {
    id: curve.id,
    paths: clipPaths(
      parsed.type === "implicit" && !curve.parametric
        ? joinSegments(paths, Math.max(xmax - xmin, ymax - ymin) * 1e-9)
        : paths,range),
  };
}
function clipPaths(paths:Vec2[][],range:number[]):Vec2[][] {
  const clipped:Vec2[][]=[];
  for(const path of paths){let line:Vec2[]=[];for(let i=1;i<path.length;i++){
    const a=path[i-1],b=path[i],dx=b[0]-a[0],dy=b[1]-a[1];let lo=0,hi=1;
    const p=[-dx,dx,-dy,dy],q=[a[0]-range[0],range[1]-a[0],a[1]-range[2],range[3]-a[1]];
    for(let k=0;k<4;k++){if(Math.abs(p[k])<1e-14){if(q[k]<0){lo=1;hi=0;break;}}else{const t=q[k]/p[k];if(p[k]<0)lo=Math.max(lo,t);else hi=Math.min(hi,t);}}
    if(lo>hi){if(line.length>1)clipped.push(line);line=[];continue;}
    const u:Vec2=[a[0]+lo*dx,a[1]+lo*dy],v:Vec2=[a[0]+hi*dx,a[1]+hi*dy],last=line.at(-1);
    if(last&&Math.hypot(last[0]-u[0],last[1]-u[1])<1e-7)line.push(v);else{if(line.length>1)clipped.push(line);line=[u,v];}
  }if(line.length>1)clipped.push(line);}
  return clipped;
}

/** Join contour cells before drawing, preserving continuous curves and dash phase. */
function joinSegments(segments: Vec2[][], epsilon: number): Vec2[][] {
  const nodes = new Map<string, { p: Vec2; edges: number[] }>();
  const key = (p: Vec2) =>
    `${Math.round(p[0] / epsilon)},${Math.round(p[1] / epsilon)}`;
  const edges = segments.map((segment, index) => {
    const ids = segment.map((p) => {
      const id = key(p),
        node = nodes.get(id) ?? { p, edges: [] };
      node.edges.push(index);
      nodes.set(id, node);
      return id;
    });
    return ids as [string, string];
  });
  const used = new Set<number>(),
    paths: Vec2[][] = [];
  const trace = (start: string, edge: number) => {
    const path: Vec2[] = [nodes.get(start)!.p];
    let current = start,
      next = edge;
    while (!used.has(next)) {
      used.add(next);
      const [a, b] = edges[next];
      current = current === a ? b : a;
      const node = nodes.get(current)!;
      path.push(node.p);
      const following = node.edges.find((e) => !used.has(e));
      if (following === undefined || node.edges.length !== 2) break;
      next = following;
    }
    if (path.length > 1) paths.push(path);
  };
  for (const [id, node] of nodes)
    if (node.edges.length !== 2)
      for (const edge of node.edges) if (!used.has(edge)) trace(id, edge);
  edges.forEach((edge, i) => {
    if (!used.has(i)) trace(edge[0], i);
  });
  return paths;
}
